ACCURACY_SPEC=spec("SFT-CHEM-ANALYTICAL-ACCURACY-TRUENESS-001","Fold analytical accuracy and trueness law","Traceable reference and held sample results force exact side/distance or structural coincidence with complete uncertainty and method boundaries.",A1_DEPS,A1_DIMS,A1_RESULT,A1_WITNESSES,"SFT-EXP-CHEM-ANALYTICAL-ACCURACY-TRUENESS-001","complete-analytical-accuracy-trueness-vector",A1_TARGETS,"Eight dimensions exhaust reference, measurand, support, comparison, trueness, uncertainty, boundary and extension.","One traceable measured/reference pair supplies the first comparison.","Every successor retains all earlier pairs and recomputes exactly.")
PRECISION_SPEC=spec("SFT-CHEM-ANALYTICAL-PRECISION-REPEATABILITY-002","Fold analytical precision and repeatability law","Same-condition replicates force all exact pair distances and extreme spread while retaining every adverse replicate separately from trueness.",A2_DEPS,A2_DIMS,A2_RESULT,A2_WITNESSES,"SFT-EXP-CHEM-ANALYTICAL-PRECISION-REPEATABILITY-002","complete-analytical-precision-repeatability-vector",A2_TARGETS,"Eight dimensions exhaust identity, conditions, support, pair comparison, spread, class, adverse custody and extension.","Two same-condition replicates supply the first pair distance.","Every successor adds all new pairs without erasing prior rows.")
